/* ================= FX ================= */
function rel(x,y){const r=app.getBoundingClientRect();return[x-r.left,y-r.top];}
function centerOf(el){const r=el.getBoundingClientRect();return[r.left+r.width/2,r.top+r.height/2];}
function sparkle(cx,cy,n=7,ch='✨'){
  const[x,y]=rel(cx,cy);
  for(let k=0;k<n;k++){const e=document.createElement('span');e.className='spark';e.textContent=ch;const a=Math.random()*Math.PI*2,d=30+Math.random()*40;e.style.cssText=`left:${x-11}px;top:${y-11}px;--dx:${Math.cos(a)*d}px;--dy:${Math.sin(a)*d}px`;fx.appendChild(e);setTimeout(()=>e.remove(),850);}
}
function floatText(cx,cy,t){const[x,y]=rel(cx,cy);const e=document.createElement('span');e.className='float';e.textContent=t;e.style.left=(x-30)+'px';e.style.top=(y-30)+'px';fx.appendChild(e);setTimeout(()=>e.remove(),1000);}
function toast(t){const e=document.createElement('div');e.className='toast';e.textContent=t;fx.appendChild(e);setTimeout(()=>e.remove(),1550);}
function buzz(){try{navigator.vibrate&&navigator.vibrate(150)}catch(e){}}

