function closeModal(w){if(w&&w.parentNode)w.remove();}

/* ================= PUZZLE ENGINE ================= */
const locked=g=>g.lock>0||!!(g.req&&g.req.some(r=>r.n>0));
const cloneGs=gs=>{const c=gs.map(g=>({lock:g.lock,sauce:g.sauce,req:g.req?g.req.map(r=>({t:r.t,n:r.n})):null,layers:g.layers.map(l=>l.map(it=>it?{t:it.t,ice:it.ice}:null))}));c.rail=(gs.rail||[]).map(r=>({t:r.t,x:r.x,id:r.id}));return c;};
const countItems=gs=>{let n=(gs.rail||[]).length;gs.forEach(g=>g.layers.forEach(l=>l.forEach(it=>{if(it)n++;})));return n;};
const isTriple=l=>l[0]&&l[1]&&l[2]&&l[0].t===l[1].t&&l[1].t===l[2].t&&!l[0].ice&&!l[1].ice&&!l[2].ice;
function afterMatch(gs,t){gs.forEach(g=>{g.layers.forEach(l=>l.forEach(it=>{if(it&&it.ice)it.ice--;}));if(g.lock>0)g.lock--;if(g.req)g.req.forEach(r=>{if(r.t===t&&r.n>0)r.n--;});});}
function resolve(gs){
  const ev={matched:[],popped:[],unlocked:[]};
  let changed=true,guard=0;
  while(changed&&guard++<60){
    changed=false;
    gs.forEach((g,i)=>{if(locked(g))return;const f=g.layers[0];if(isTriple(f)){const t=f[0].t;ev.matched.push({g:i,t});g.layers[0]=[null,null,null];changed=true;const before=gs.map(locked);afterMatch(gs,t);gs.forEach((x,j)=>{if(before[j]&&!locked(x))ev.unlocked.push(j);});}});
    gs.forEach((g,i)=>{if(locked(g))return;if(g.layers[0].every(x=>!x)&&g.layers.length>1){g.layers.shift();ev.popped.push(i);changed=true;}});
  }
  return ev;
}
const canPick=(gs,g,p)=>{if(g===-1)return !!(gs.rail&&gs.rail[p]);const x=gs[g];if(!x||locked(x))return false;const it=x.layers[0][p];return !!(it&&!it.ice);};
const canDrop=(gs,g,p)=>{if(g<0)return false;const x=gs[g];return !!x&&!locked(x)&&!x.layers[0][p];};
function doMove(gs,a,b){let it;if(a.g===-1){it={t:gs.rail[a.p].t,ice:0};gs.rail.splice(a.p,1);}else{it=gs[a.g].layers[0][a.p];gs[a.g].layers[0][a.p]=null;}gs[b.g].layers[0][b.p]=it;}
function bestMove(gs){
  const src=[],dst=[];
  gs.forEach((g,gi)=>{if(locked(g))return;g.layers[0].forEach((it,p)=>{if(it&&!it.ice)src.push({g:gi,p,t:it.t});else if(!it)dst.push({g:gi,p});});});
  (gs.rail||[]).forEach((r,i)=>src.push({g:-1,p:i,t:r.t,id:r.id}));
  if(!src.length||!dst.length)return null;
  const cnt=gi=>gi<0?1.5:gs[gi].layers[0].filter(Boolean).length;
  const typesIn=(gi,t)=>gi<0?0:gs[gi].layers[0].filter(x=>x&&x.t===t).length;
  for(const d of dst){const items=gs[d.g].layers[0].filter(Boolean);if(items.length===2&&items[0].t===items[1].t&&!items[0].ice&&!items[1].ice){const t=items[0].t;const cs=src.filter(s=>s.t===t&&s.g!==d.g);if(cs.length){cs.sort((a,b)=>cnt(a.g)-cnt(b.g));return{a:cs[0],b:d};}}}
  for(const d of dst){const items=gs[d.g].layers[0].filter(Boolean);if(items.length===1&&!items[0].ice){const t=items[0].t;const cs=src.filter(s=>s.t===t&&s.g!==d.g&&typesIn(s.g,t)<2);if(cs.length){cs.sort((a,b)=>cnt(a.g)-cnt(b.g));return{a:cs[0],b:d};}}}
  const ss=src.filter(s=>typesIn(s.g,s.t)<2).sort((a,b)=>cnt(a.g)-cnt(b.g));
  for(const s of ss){const ds=dst.filter(d=>d.g!==s.g);if(ds.length){ds.sort((a,b)=>cnt(a.g)-cnt(b.g));const pref=ds.find(d=>typesIn(d.g,s.t)>0);return{a:s,b:pref||ds[ds.length-1]};}}
  for(const s of src){const d=dst.find(d=>d.g!==s.g);if(d)return{a:s,b:d};}
  return null;
}
function solvable(gs){const s=cloneGs(gs);for(let i=0;i<1200;i++){if(countItems(s)===0)return true;const m=bestMove(s);if(!m)return false;doMove(s,m.a,m.b);resolve(s);}return false;}
// 스테이지 종류: 5의 배수(10~) = 매운맛 하드, 끝자리 3·8(8~) = 레일
function stageType(n){if(n>=10&&n%5===0)return 'hard';if(n>=8&&n%5===3)return 'rail';return 'normal';}
function levelCfg(n){
  const T=[[6,4,8],[6,5,10],[9,6,13],[9,7,15],[9,7,16],[12,8,18],[12,8,20],[12,9,21],[12,10,22],[12,10,24]];
  let[grills,types,sets]=T[Math.min(n-1,T.length-1)];
  if(n>10){sets=Math.min(30,24+Math.floor((n-10)/2));types=Math.min(12,10+Math.floor((n-10)/3));}
  const prog=n>22?(Math.min(n,100)-22)/78:0;if(n>22)sets=30+Math.round(6*prog);
  const stage=stageType(n);
  let locks=n>=4?(n>=8?2:1):0,ice=n>=5?Math.min(6,n-3):0,iron=n>=7?1:0,sauce=0,rail=0;
  if(iron&&locks>0)locks--;
  // 하드: 양념 판 + 세트·시간 압박에, 장치는 한 판에 하나만 (얼음 → 주문 철판 → 뚜껑 순서로 돌아가며)
  if(stage==='hard'){sets=Math.min(40,Math.round(sets*1.2));sauce=Math.round(grills/3);ice=0;locks=0;iron=0;const k=Math.floor(n/5)%3;if(k===2)ice=4;else if(k===0)iron=1;else locks=1;}
  if(stage==='rail'){grills=Math.min(grills,9);rail=1;}
  let time=Math.round(50+sets*(7-prog));if(stage==='hard')time=Math.round(time*.85);if(rail)time+=15;
  return{n,stage,grills,types,sets,locks,ice,iron,sauce,rail,orders:n>=3,time};
}
function genLevel(cfg){
  let last=null;
  for(let att=0;att<120;att++){
    const u=unlockedCount(cfg.n),newest=MENU_ORDER[u-1];
    const typesSel=[newest,...shuffle(MENU_ORDER.slice(0,u-1)).slice(0,Math.min(cfg.types,u)-1)];
    const pool=[];for(let s=0;s<cfg.sets;s++){const t=typesSel[s%typesSel.length];pool.push(t,t,t);}shuffle(pool);
    const N=cfg.grills;const gs=Array.from({length:N},()=>({lock:0,sauce:false,req:null,layers:[[null,null,null]]}));
    gs.rail=[];
    if(cfg.rail){const rn=Math.round(pool.length*.3);for(let i=0;i<rn;i++)gs.rail.push({t:pool.pop(),x:i,id:i+1});}
    const E=(N<=6?4:N<=9?5:6)+(cfg.rail?1:0);
    const frontCount=Math.min(pool.length,N*3-E);
    shuffle([...Array(N*3).keys()]).slice(0,frontCount).forEach(si=>{gs[Math.floor(si/3)].layers[0][si%3]={t:pool.pop(),ice:0};});
    let gi=rnd(N),guard=0;
    while(pool.length&&guard++<500){const g=gs[gi%N];if(g.layers.length<7){const k=Math.min(pool.length,2+(Math.random()<.5?1:0));const layer=[null,null,null];shuffle([0,1,2]).slice(0,k).forEach(p=>{layer[p]={t:pool.pop(),ice:0};});g.layers.push(layer);}gi+=1+rnd(2);}
    gs.forEach(g=>{while(g.layers[0].every(x=>!x)&&g.layers.length>1)g.layers.shift();});
    if(gs.some(g=>isTriple(g.layers[0])))continue;
    const order=shuffle(gs.map((g,i)=>i));let li=0;
    for(let k=0;k<cfg.locks&&li<N;k++)gs[order[li++]].lock=3+k*3;
    for(let k=0;k<cfg.iron&&li<N;k++){
      const gk=order[li++],cnts={};
      gs.forEach((g,j)=>{if(j===gk)return;g.layers.forEach(l=>l.forEach(it=>{if(it)cnts[it.t]=(cnts[it.t]||0)+1;}));});
      gs.rail.forEach(r=>cnts[r.t]=(cnts[r.t]||0)+1);
      const ok=shuffle(Object.keys(cnts).map(Number).filter(t=>cnts[t]>=3));
      const req=ok.slice(0,Math.min(ok.length,Math.random()<.5?2:1)).map(t=>({t,n:1}));
      gs[gk].req=req.length?req:null;
    }
    if(cfg.ice){const fr=[];gs.forEach(g=>{if(locked(g))return;g.layers[0].forEach(it=>{if(it)fr.push(it);});});shuffle(fr).slice(0,cfg.ice).forEach(it=>it.ice=2);}
    if(cfg.sauce)shuffle(gs.filter(g=>!locked(g)&&g.layers.length>1)).slice(0,cfg.sauce).forEach(g=>g.sauce=true);
    last=gs;
    if(solvable(gs))return gs;
  }
  return last;
}
/* ================= LEVEL UI ================= */
let L=null,drag=null,timerInt=null,hintTO=null,tutHand=null;
(function lights(){
  const C=['#ff5a5f','#ffd166','#06d6a0','#4cc9f0','#ff8fab'];
  const q=(t,a,b,c2)=>(1-t)*(1-t)*a+2*(1-t)*t*b+t*t*c2;
  let s='<path d="M0 8 Q100 46 200 16 Q300 46 400 8" stroke="#1a1020" stroke-width="2" fill="none"/>';
  for(let i=0;i<=16;i++){const T=i/16;let x,y;if(T<=.5){const t=T*2;x=q(t,0,100,200);y=q(t,8,46,16);}else{const t=(T-.5)*2;x=q(t,200,300,400);y=q(t,16,46,8);}
    s+=`<circle class="bulb" cx="${x}" cy="${y+5}" r="5" fill="${C[i%C.length]}" style="animation-delay:${-i*.3}s;filter:drop-shadow(0 0 4px ${C[i%C.length]})"/>`;}
  $('#lights').innerHTML=s;
})();
function runTimer(){
  clearInterval(timerInt);
  let prev=performance.now();
  timerInt=setInterval(()=>{
    const now=performance.now(),dt=(now-prev)/1000;prev=now;
    if(!L||!L.running||L.paused)return;
    L.time-=dt;L.elapsed=(L.elapsed||0)+dt;
    if(now>=(L.nextSmoke||0)){L.nextSmoke=now+1100+Math.random()*1700;const cs=L.gs.map((g,i)=>i).filter(i=>!locked(L.gs[i])&&L.gs[i].layers[0].some(Boolean));if(cs.length)smokeAt(cs[rnd(cs.length)],2+rnd(2));}
    if(L.cfg.orders){
      if(!L.order&&L.elapsed>=L.nextOrder&&!spawnOrder())L.nextOrder=L.elapsed+5;
      if(L.order&&!L.order.result){
        L.order.left-=dt;
        if(L.order.left<=0)finishOrder(false);
        else renderOrder();
      }
    }
    if(L.combo>0){const f=1-(now-L.last)/7000;if(f<=0){L.combo=0;$('#comboBox').classList.remove('on');}else $('#comboBar').style.width=(f*100)+'%';}
    if(L.time<=0){L.time=0;updLevelHud();timeUp();return;}
    updLevelHud();
  },100);
}
function updLevelHud(){
  const t=Math.ceil(L.time);$('#timer').textContent=`⏱ ${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;
  $('#timer').classList.toggle('low',L.time<=15);
  $('#servTxt').innerHTML=`${ICO('served')} ${L.served}/${L.cfg.sets}`;
}
const BCOST={hint:60,shuffle:100,bag:150,time:80};
function updBoosters(){
  document.querySelectorAll('.bst').forEach(b=>{const k=b.dataset.b,n=b.querySelector('.n');if(D.boost[k]>0){n.textContent=D.boost[k];n.classList.remove('buy');}else{n.textContent='🪙'+BCOST[k];n.classList.add('buy');}});
}
function renderBoard(o={}){
  const rows=L.gs.length/3;
  boardEl.style.gridTemplateRows=`repeat(${rows},auto)`;
  const bw=boardEl.clientWidth||360,bh=boardEl.clientHeight||500;
  const colW=(bw-12-12)/3;
  boardEl.style.setProperty('--rh',Math.max(60,Math.min(colW/1.45,(bh-12-6*(rows-1))/rows-24))+'px');
  boardEl.innerHTML=L.gs.map((g,gi)=>{
    const f=g.layers[0],nx=g.layers[1];
    const slots=f.map((it,p)=>{
      let cls='slot';
      if(L.sel&&L.sel.g===gi&&L.sel.p===p)cls+=' sel';
      if(o.rise&&o.rise.includes(gi))cls+=' rise';
      if(o.placed&&o.placed.g===gi&&o.placed.p===p)cls+=' placed';
      return `<div class="${cls}" data-g="${gi}" data-p="${p}">${it?FOOD_SVG[it.t]+(it.ice?`<span class="ice i${Math.min(2,it.ice)}"></span>`:''):''}</div>`;
    }).join('');
    const lk=locked(g);
    const lid=g.lock>0?`<div class="lid"><div class="lw"><span>${g.lock}</span></div></div>`:lk?`<div class="lid iron"><div class="lw"><span class="req">${g.req.filter(r=>r.n>0).map(r=>`<i>${FOOD_SVG[r.t]}</i>`).join('')}</span></div></div>`:(o.unlocked&&o.unlocked.includes(gi)?`<div class="lid open${g.req?' iron':''}"><div class="lw"></div></div>`:'');
    const pn=g.layers.length-1,plate=`<div class="plate n${Math.min(3,pn)}${o.rise&&o.rise.includes(gi)?' drop':''}">${nx&&!lk?nx.map(it=>`<i>${it?(g.sauce?'<span class="sq">?</span>':FOOD_SVG[it.t]):''}</i>`).join(''):''}${pn>3&&!lk?`<b class="more">+${pn-3}</b>`:''}</div>`;
    return `<div class="grill${g.sauce?' sauce':''}${lk?' lk':''}" data-g="${gi}"><div class="rack">${g.sauce&&!lk?'<span class="chili">🌶️</span>':''}${slots}${lid}</div>${plate}</div>`;
  }).join('');
}
function slotEl(g,p){return boardEl.querySelector(`.slot[data-g="${g}"][data-p="${p}"]`);}
function clearHints(){clearTimeout(hintTO);boardEl.querySelectorAll('.hintsrc,.hintdst').forEach(e=>e.classList.remove('hintsrc','hintdst'));if(tutHand){tutHand.remove();tutHand=null;}}
function showHand(a,b,keep){
  if(tutHand)tutHand.remove();
  const ea=srcEl(a),eb=slotEl(b.g,b.p);if(!ea||!eb)return;
  const[x0,y0]=rel(...centerOf(ea)),[x1,y1]=rel(...centerOf(eb));
  tutHand=document.createElement('div');tutHand.className='thand';tutHand.textContent='👆';
  tutHand.style.cssText=`left:0;top:0;--x0:${x0-14}px;--y0:${y0}px;--x1:${x1-14}px;--y1:${y1}px`;
  fx.appendChild(tutHand);
  if(!keep)hintTO=setTimeout(clearHints,3200);
}
function srcEl(a){return a.g===-1?document.querySelector(`.ritem[data-id="${a.id}"]`):slotEl(a.g,a.p);}
function showTutorial(){const m=bestMove(L.gs);if(m){srcEl(m.a)?.classList.add('hintsrc');slotEl(m.b.g,m.b.p)?.classList.add('hintdst');showHand(m.a,m.b,true);}}
function nearestEmpty(g,clientX){
  if(locked(L.gs[g]))return null;
  let best=null,bd=1e9;
  L.gs[g].layers[0].forEach((it,p)=>{if(it)return;const e=slotEl(g,p);if(!e)return;const[x]=centerOf(e);const d=Math.abs(x-clientX);if(d<bd){bd=d;best={g,p};}});
  return best;
}
function targetFrom(el,x){
  if(!el)return null;
  const s=el.closest('.slot');
  if(s){const g=+s.dataset.g,p=+s.dataset.p;if(canDrop(L.gs,g,p))return{g,p};return nearestEmpty(g,x);}
  const gr=el.closest('.grill');if(gr)return nearestEmpty(+gr.dataset.g,x);
  return null;
}
function wiggle(el){el.classList.remove('wig');void el.offsetWidth;el.classList.add('wig');sfx('err');}
boardEl.addEventListener('pointerdown',e=>{
  if(!L||!L.running||L.busy||L.paused)return;
  const sl=e.target.closest('.slot');
  if(!sl){const gr=e.target.closest('.grill');if(gr&&L.sel){const t=nearestEmpty(+gr.dataset.g,e.clientX);if(t)tryMove(L.sel,t);}return;}
  const g=+sl.dataset.g,p=+sl.dataset.p;
  if(locked(L.gs[g])){wiggle(sl);const G0=L.gs[g];toast(G0.lock>0?`🔒 세트를 ${G0.lock}번 더 맞추면 열려요`:`⛓️ ${G0.req.filter(r=>r.n>0).map(r=>FOODS[r.t].n).join('·')} 세트를 맞추면 열려요`);return;}
  const it=L.gs[g].layers[0][p];
  if(!it){if(L.sel)tryMove(L.sel,{g,p});return;}
  if(it.ice){wiggle(sl);return;}
  e.preventDefault();
  if(!(L.sel&&L.sel.g===g&&L.sel.p===p)){sfx('pick');document.querySelectorAll('.slot.sel,.ritem.sel').forEach(x=>x.classList.remove('sel'));sl.classList.add('sel');}
  drag={g,p,t:it.t,x0:e.clientX,y0:e.clientY,moved:false,ghost:null,el:sl,pid:e.pointerId};
});
window.addEventListener('pointermove',e=>{
  if(!drag)return;
  const dx=e.clientX-drag.x0,dy=e.clientY-drag.y0;
  if(!drag.moved&&Math.hypot(dx,dy)>8){
    drag.moved=true;L.sel=null;boardEl.querySelectorAll('.slot.sel').forEach(s=>s.classList.remove('sel'));
    const r=drag.el.getBoundingClientRect();
    const gh=document.createElement('div');gh.className='ghost';gh.style.height=r.height+'px';gh.innerHTML=FOOD_SVG[drag.t];
    fx.appendChild(gh);drag.ghost=gh;drag.el.classList.remove('sel');drag.el.classList.add('lift');
  }
  if(drag.ghost){const[x,y]=rel(e.clientX,e.clientY);drag.ghost.style.left=x+'px';drag.ghost.style.top=y+'px';}
});
function endDrag(e,cancel){
  if(!drag)return;const d=drag;drag=null;
  if(d.ghost){
    d.ghost.remove();d.el.classList.remove('lift');
    if(cancel){renderBoard();return;}
    const t=targetFrom(document.elementFromPoint(e.clientX,e.clientY),e.clientX);
    if(t&&!(t.g===d.g&&t.p===d.p))tryMove({g:d.g,p:d.p,id:d.id},t);else{renderBoard();renderRail();}
  }else if(!cancel){
    if(L.sel&&L.sel.g===d.g&&(d.g===-1?L.sel.id===d.id:L.sel.p===d.p))L.sel=null;else L.sel={g:d.g,p:d.p,id:d.id};
    renderBoard();renderRail();
  }
}
window.addEventListener('pointerup',e=>endDrag(e,false));
window.addEventListener('pointercancel',e=>endDrag(e,true));

function tryMove(a,b){
  if(!L||L.busy)return;
  if(a.g===-1){const ri=L.gs.rail.findIndex(r=>r.id===a.id);if(ri<0)return;a={g:-1,p:ri,id:a.id};}
  if(a.g===b.g&&a.p===b.p)return;
  if(!canPick(L.gs,a.g,a.p)||!canDrop(L.gs,b.g,b.p))return;
  clearHints();
  doMove(L.gs,a,b);L.sel=null;L.moved=true;sizzle();
  if(a.g===-1)renderRail();
  renderBoard({placed:b});smokeAt(b.g,2);
  L.busy=true;
  setTimeout(()=>{
    const pre=cloneGs(L.gs);
    const ev=resolve(L.gs);
    if(ev.matched.length){
      ev.matched.forEach((m,k)=>{
        setTimeout(()=>collectAnim(m.g,m.t),k*120);orderMatched(m.t,L.gs[m.g].sauce);
        const now=performance.now();
        L.combo=(now-L.last<7000&&L.combo>0)?L.combo+1:1;L.last=now;L.maxCombo=Math.max(L.maxCombo||0,L.combo);
        if(L.combo>1){L.bonus+=Math.min(L.combo,10)*3;}
      });
      L.served+=ev.matched.length;
      if(L.combo>1){$('#comboTxt').textContent='콤보 x'+L.combo;const sv=$('#servTxt');const[x,y]=centerOf(boardEl);floatText(x,y-60,`콤보 x${L.combo}! 🔥`);}
      $('#comboBox').classList.toggle('on',L.combo>0);$('#comboTxt').textContent='콤보 x'+L.combo;$('#comboBar').style.width='100%';
      setTimeout(()=>{renderBoard({rise:ev.popped,unlocked:ev.unlocked});updLevelHud();L.busy=false;checkEnd();},330);
    }else{
      if(ev.popped.length)renderBoard({rise:ev.popped});
      L.busy=false;checkEnd();
    }
  },130);
}
const PLATE=`<svg viewBox="0 0 100 62" xmlns="http://www.w3.org/2000/svg"><image href="${IMG.serve}" x="0" y="0" width="100" height="62" preserveAspectRatio="none"/></svg>`;
function clack(i){
  if(D.mute)return;
  try{if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();if(AC.state==='suspended')AC.resume();ensureNoise();const t=AC.currentTime;
    tone('triangle',1500+i*260,900+i*200,t,.06,.09);noiseHit(t,.035,3800+i*400,.07);}catch(e){}
}
function whoosh(){
  if(D.mute)return;
  try{ensureNoise();const t=AC.currentTime;const src=AC.createBufferSource();src.buffer=noiseBuf;const bp=AC.createBiquadFilter();bp.type='bandpass';bp.Q.value=.9;bp.frequency.setValueAtTime(900,t);bp.frequency.exponentialRampToValueAtTime(3200,t+.3);const g=AC.createGain();g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.05,t+.08);g.gain.exponentialRampToValueAtTime(.0001,t+.32);src.connect(bp).connect(g).connect(AC.destination);src.start(t);src.stop(t+.35);}catch(e){}
}
function collectAnim(gi,t){
  const els=[0,1,2].map(p=>slotEl(gi,p)).filter(Boolean);if(!els.length)return;
  const rack=els[0].closest('.rack');const rr=(rack||els[0]).getBoundingClientRect();
  const rs=els.map(e=>{const sv=e.querySelector('svg');return(sv||e).getBoundingClientRect();});
  els.forEach(e=>e.classList.add('collected'));
  const W=rr.width*.92,H=W*.62;
  const[cx,cy]=rel(rr.left+rr.width/2,rr.top+rr.height*.58);
  const pk=document.createElement('div');pk.className='platepack';
  pk.style.cssText=`left:${cx-W/2}px;top:${cy-H/2}px;width:${W}px;height:${H}px`;
  pk.innerHTML=PLATE;fx.appendChild(pk);
  const spots=[[.40,.60,-74],[.52,.50,-66],[.62,.40,-58]];
  const STEP=95,FLY=150;
  rs.forEach((r,i)=>{
    const[sp,sy,rot]=spots[i];
    const tx=cx-W/2+W*sp,ty=cy-H/2+H*sy;
    const sc=(W*.62)/Math.max(r.height,1);
    setTimeout(()=>{
      const f=document.createElement('div');f.className='cflyer';
      const[x,y]=rel(r.left,r.top);
      f.style.cssText=`left:${x}px;top:${y}px;width:${r.width}px;height:${r.height}px;transition:transform ${FLY}ms cubic-bezier(.3,.7,.4,1)`;
      f.innerHTML=FOOD_SVG[t];fx.appendChild(f);
      requestAnimationFrame(()=>requestAnimationFrame(()=>{f.style.transform=`translate(${tx-(x+r.width/2)}px,${ty-(y+r.height/2)}px) rotate(${rot}deg) scale(${sc})`;}));
      setTimeout(()=>{
        f.remove();
        const it=document.createElement('span');it.className='onplate';
        it.style.cssText=`left:${tx-(cx-W/2)-r.width/2}px;top:${ty-(cy-H/2)-r.height/2}px;width:${r.width}px;height:${r.height}px;transform:rotate(${rot}deg) scale(${sc})`;
        it.innerHTML=FOOD_SVG[t];pk.appendChild(it);
        clack(i);pk.classList.remove('thud');void pk.offsetWidth;pk.classList.add('thud');
      },FLY);
    },60+i*STEP);
  });
  const landed=60+2*STEP+FLY;
  setTimeout(()=>{
    const r=app.getBoundingClientRect();sparkle(r.left+cx,r.top+cy,7);
    const[tx,ty]=rel(...centerOf($('#servTxt')));
    pk.classList.add('go');pk.style.transform=`translate(${tx-cx}px,${ty-cy}px) scale(.28)`;pk.style.opacity='.35';whoosh();
  },landed+160);
  setTimeout(()=>{pk.remove();const sv=$('#servTxt');sv.style.transform='scale(1.25)';setTimeout(()=>sv.style.transform='',160);},landed+160+480);
}
const TZ=(()=>{const lh=document.querySelector('.lvhead'),tz=document.createElement('div');tz.className='topzone';lh.parentNode.insertBefore(tz,lh);lh.appendChild(document.querySelector('#servTxt'));tz.append(lh,document.querySelector('.lvinfo'),document.querySelector('#counter'));return tz;})();
function updTopBg(){const W=TZ.clientWidth,T=TZ.clientHeight;if(!W||!T)return;const H=W*1024/1536;TZ.style.backgroundPosition=`center ${Math.round(T-18-H*.785)}px`;}
try{new ResizeObserver(updTopBg).observe(TZ);}catch(e){}
function smokeAt(gi,n){
  if(!L)return;const g=boardEl.querySelector(`.grill[data-g="${gi}"] .rack`);if(!g)return;
  const r=g.getBoundingClientRect(),[x0,y0]=rel(r.left,r.top);
  for(let k=0;k<n;k++){const e=document.createElement('i');e.className='smoke';const sz=r.width*(.26+Math.random()*.2);
    e.style.cssText=`left:${x0+r.width*(.2+Math.random()*.6)-sz/2}px;top:${y0+r.height*(.3+Math.random()*.35)-sz/2}px;width:${sz}px;height:${sz}px;animation-delay:${k*.28}s;--dx:${((Math.random()-.5)*34).toFixed(1)}px`;
    fx.appendChild(e);setTimeout(()=>e.remove(),3000+k*300);}
}
function flyToCounter(fromEl,t){
  const[x0,y0]=rel(...centerOf(fromEl));const[x1,y1]=rel(...centerOf($('#servTxt')));
  const f=document.createElement('div');f.className='flyer';f.innerHTML=FOOD_SVG[t];f.style.left=(x0-17)+'px';f.style.top=(y0-30)+'px';
  fx.appendChild(f);
  requestAnimationFrame(()=>requestAnimationFrame(()=>{f.style.transform=`translate(${x1-x0}px,${y1-y0}px) scale(.5)`;f.style.opacity='.3';}));
  setTimeout(()=>{f.remove();const s=$('#servTxt');s.style.transform='scale(1.2)';setTimeout(()=>s.style.transform='',150);},560);
}
function checkEnd(){
  if(!L.running)return;
  if(countItems(L.gs)===0){winLevel();return;}
  if(!bestMove(L.gs))stuck();
}
function stopLevel(){L.running=false;clearInterval(timerInt);clearHints();if(L.order)L.order=null;renderOrder();}
document.querySelectorAll('.bst').forEach(b=>b.onclick=()=>useBooster(b.dataset.b));
function useBooster(k){
  if(!L||!L.running||L.busy)return;
  if(D.boost[k]>0)D.boost[k]--;
  else if(D.coins>=BCOST[k]){D.coins-=BCOST[k];}
  else{toast('🪙 코인이 부족해요');sfx('err');return;}
  save();updBoosters();updCoins();sfx('buy');clearHints();L.sel=null;
  if(k==='hint'){
    const m=bestMove(L.gs);
    if(!m){toast('움직일 수 있는 게 없어요');renderBoard();return;}
    renderBoard();renderRail();srcEl(m.a)?.classList.add('hintsrc');slotEl(m.b.g,m.b.p)?.classList.add('hintdst');showHand(m.a,m.b,false);
  }else if(k==='time'){L.time+=30;updLevelHud();toast('⏰ +30초!');}
  else if(k==='shuffle'){
    const pos=[];L.gs.forEach((g,gi)=>{if(locked(g))return;g.layers[0].forEach((it,p)=>{if(it&&!it.ice)pos.push({g:gi,p,it});});});
    let best=null,bs=-1;
    for(let t=0;t<40;t++){const items=shuffle(pos.map(x=>x.it));const tmp=cloneGs(L.gs);pos.forEach((x,i)=>{tmp[x.g].layers[0][x.p]={t:items[i].t,ice:0};});
      let sc=0;tmp.forEach(g=>{if(locked(g))return;const f=g.layers[0].filter(Boolean);const m={};f.forEach(i=>m[i.t]=(m[i.t]||0)+1);Object.values(m).forEach(v=>{if(v>=3)sc+=10;else if(v===2)sc+=2;});});
      if(sc>bs){bs=sc;best=items;}}
    pos.forEach((x,i)=>{L.gs[x.g].layers[0][x.p]={t:best[i].t,ice:0};});
    renderBoard({rise:L.gs.map((_,i)=>i)});toast('🔄 섞었어요!');
    L.busy=true;setTimeout(()=>{L.busy=false;afterAuto();},380);
  }else if(k==='bag'){
    const m={};L.gs.forEach(g=>{if(locked(g))return;g.layers[0].forEach(it=>{if(it)m[it.t]=(m[it.t]||0)+1;});});
    let t=-1,mx=0;for(const x in m)if(m[x]>mx){mx=m[x];t=+x;}
    if(t<0){L.gs.forEach(g=>g.layers.forEach(l=>l.forEach(it=>{if(it&&t<0)t=it.t;})));}
    let need=3;
    const take=(onlyFront)=>{L.gs.forEach((g,gi)=>{if(onlyFront&&locked(g))return;(onlyFront?[g.layers[0]]:g.layers).forEach(l=>l.forEach((it,p)=>{if(need>0&&it&&it.t===t){const s=onlyFront?slotEl(gi,p):null;if(s){const[x,y]=centerOf(s);sparkle(x,y,5);}l[p]=null;need--;}}));});};
    take(true);for(let i=L.gs.rail.length-1;i>=0&&need>0;i--)if(L.gs.rail[i].t===t){L.gs.rail.splice(i,1);need--;}if(need>0)take(false);
    L.served++;afterMatch(L.gs,t);orderMatched(t,false);renderRail();
    toast(`🛍️ ${FOODS[t].n} 포장 완료!`);
    L.busy=true;setTimeout(()=>{L.busy=false;afterAuto();},300);
  }
}
function afterAuto(){
  const ev=resolve(L.gs);
  if(ev.matched.length){L.served+=ev.matched.length;sfx('match');ev.matched.forEach(m=>orderMatched(m.t,L.gs[m.g].sauce));}
  L.gs.forEach(g=>{while(!locked(g)&&g.layers[0].every(x=>!x)&&g.layers.length>1)g.layers.shift();});
  renderBoard({rise:ev.popped,unlocked:ev.unlocked});updLevelHud();checkEnd();
}


/* ================= 손님 주문 ================= */
const NPC={"rider":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"grandma":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"office":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"student":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"kid":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"worker":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"nurse":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"},"police":{"dot":"data:image/webp;base64,","smile":"data:image/webp;base64,","angry":"data:image/webp;base64,"}};
